insert into detection_rules (rule_id,title,detector,logic,mitre_tags,severity) values ('R-NET-BRUTEFORCE','Network brute force (FTP/SSH)','rule','{"ref": "R-NET-BRUTEFORCE"}'::jsonb,ARRAY['T1110']::text[],'high') on conflict (rule_id) do nothing;
insert into detection_rules (rule_id,title,detector,logic,mitre_tags,severity) values ('R-NET-FLOOD','Volumetric flood / DDoS','rule','{"ref": "R-NET-FLOOD"}'::jsonb,ARRAY['T1498']::text[],'high') on conflict (rule_id) do nothing;
insert into detection_rules (rule_id,title,detector,logic,mitre_tags,severity) values ('flow_rate_zscore','Anomalous flow packet-rate','statistical','{"ref": "flow_rate_zscore"}'::jsonb,ARRAY['T1498']::text[],'medium') on conflict (rule_id) do nothing;
insert into detection_rules (rule_id,title,detector,logic,mitre_tags,severity) values ('R-NET-BEACON','Botnet C2 beaconing','ioc','{"ref": "R-NET-BEACON"}'::jsonb,ARRAY['T1071']::text[],'high') on conflict (rule_id) do nothing;
insert into attack_kb (technique_id,name,tactic,description) values ('T1110','Brute Force','Credential Access','Adversaries systematically guess credentials via repeated authentication attempts, e.g. FTP/SSH password guessing (Patator, Hydra).') on conflict (technique_id) do nothing;
insert into attack_kb (technique_id,name,tactic,description) values ('T1498','Network Denial of Service','Impact','Adversaries flood a target with traffic to exhaust bandwidth or resources, degrading availability (e.g. HTTP flood via LOIC).') on conflict (technique_id) do nothing;
insert into attack_kb (technique_id,name,tactic,description) values ('T1071','Application Layer Protocol','Command and Control','Adversaries use common application-layer protocols (HTTP/HTTPS on ports like 8080) for C2 beaconing so traffic blends with normal activity.') on conflict (technique_id) do nothing;
insert into attack_kb (technique_id,name,tactic,description) values ('T1499','Endpoint Denial of Service','Impact','Adversaries exhaust the resources of a specific service or host to make it unavailable.') on conflict (technique_id) do nothing;
insert into attack_kb (technique_id,name,tactic,description) values ('T1571','Non-Standard Port','Command and Control','Adversaries use non-standard ports (e.g. 8080 for HTTP C2) to bypass filtering and blend in.') on conflict (technique_id) do nothing;
